add_filter( 'body_class', 'perfectpixel_category_body_class' );

function perfectpixel_category_body_class( $classes ) {
	if ( ! function_exists( 'is_product' ) || ! is_product() ) {
		return $classes;
	}
	$ids = wp_get_post_terms( get_queried_object_id(), 'product_cat', array( 'fields' => 'ids' ) );
	foreach ( (array) $ids as $id ) {
		foreach ( array_merge( array( $id ), get_ancestors( $id, 'product_cat', 'taxonomy' ) ) as $term_id ) {
			$term = get_term( $term_id, 'product_cat' );
			if ( $term && ! is_wp_error( $term ) ) {
				$classes[] = 'product-cat-' . sanitize_html_class( $term->slug );
			}
		}
	}
	return array_unique( $classes );
}
